var Url = [
  "https://www.freeacg.org",
  "https://www.freeacg3.org",
  "https://www.acgbay.com"
]

function URL() {	
	 let v = String(this.source.getVariable()).split(",");
   let x = String(v[0]);
   return Url[x]===undefined?this.source.key:Url[x]
}

