var next=result[0],
location=url=>({href:url});
u=eval(String(next));
w=",{'webView': true}";
/_\d+.html?$/.test(u)&&u+w;
}

ruleContent.content:
#chaptercontent > p!-1@html
@js:
atob = str => java.base64Decode(str);
try{
	c = src.match(/var c="([^"]+)"/)[1].toString();
	a = atob(c.slice(Number(c.slice(4, 6)) + 6, c.length - Number(c.slice(4, 6))).replace(/_/g, "8L3A+").replace(/-/g, "PHA+"));
	result + a;
	}catch(e){
		java.log(e)
		result
		}

